-- Disposable local contract fixture; never a hosted migration.
CREATE SCHEMA auth;CREATE TABLE auth.users(id uuid PRIMARY KEY);CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;GRANT USAGE ON SCHEMA auth TO anon,authenticated;
CREATE TABLE profiles(id uuid primary key,role text,is_active boolean,phone text,latitude float8,longitude float8);CREATE TABLE seller_profiles(id uuid primary key,owner_id uuid,business_type text,status text,verification_status text);
CREATE TABLE service_provider_listings(id uuid primary key,owner_id uuid,provider_type text,status text,title text,name text,phone text,message_contact text,specialty text,services text,about text,experience text,working_hours text,region text,district text,address text,latitude float8,longitude float8,rating numeric(3,2),reviews_count integer,promotion_type text,promotion_started_at timestamptz,promotion_until timestamptz,last_boosted_at timestamptz,created_at timestamptz,updated_at timestamptz,published_at timestamptz,details jsonb,seller_profile_id uuid);
CREATE TABLE service_provider_media(id uuid primary key,listing_id uuid,owner_id uuid,media_type text,storage_path text,sort_order integer,is_cover boolean,created_at timestamptz);
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;ALTER TABLE seller_profiles ENABLE ROW LEVEL SECURITY;ALTER TABLE service_provider_listings ENABLE ROW LEVEL SECURITY;ALTER TABLE service_provider_media ENABLE ROW LEVEL SECURITY;GRANT SELECT ON service_provider_listings,service_provider_media TO anon,authenticated;GRANT INSERT,UPDATE,DELETE ON service_provider_listings,service_provider_media TO authenticated;
CREATE POLICY service_provider_active_public_select ON service_provider_listings FOR SELECT TO anon,authenticated USING(status='active' OR owner_id=auth.uid());CREATE POLICY service_provider_listings_public_select ON service_provider_listings FOR SELECT TO anon,authenticated USING(status='active' OR owner_id=auth.uid());CREATE POLICY owner_insert ON service_provider_listings FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid());CREATE POLICY owner_update ON service_provider_listings FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());CREATE POLICY owner_delete ON service_provider_listings FOR DELETE TO authenticated USING(owner_id=auth.uid());
CREATE POLICY service_provider_media_public_select ON service_provider_media FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM service_provider_listings l WHERE l.id=listing_id AND(l.status='active' OR l.owner_id=auth.uid())));CREATE POLICY service_provider_media_owner_update ON service_provider_media FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE SCHEMA storage;CREATE TABLE storage.buckets(id text primary key,public boolean);INSERT INTO storage.buckets VALUES('provider-media',false);CREATE TABLE storage.objects(id uuid primary key,bucket_id text,name text);ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;GRANT USAGE ON SCHEMA storage TO anon,authenticated;GRANT SELECT ON storage.objects TO anon,authenticated;CREATE POLICY austa_provider_media_select_active_or_own ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='provider-media' AND EXISTS(SELECT 1 FROM public.service_provider_listings l WHERE l.id::text=split_part(name,'/',2) AND(l.status='active' OR l.owner_id=auth.uid())));
