ALTER TABLE public.profiles ADD COLUMN phone_verified boolean DEFAULT false;
GRANT UPDATE ON public.profiles TO authenticated;
CREATE POLICY profile_own_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY profile_own_select ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
GRANT SELECT ON public.profiles TO authenticated;
CREATE FUNCTION public.austa_protect_profile_security_fields() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF auth.uid() IS NOT NULL THEN
  IF NEW.role IS DISTINCT FROM OLD.role THEN RAISE EXCEPTION 'Protected role'; END IF;
  IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN RAISE EXCEPTION 'Protected active'; END IF;
  IF NEW.phone_verified IS DISTINCT FROM OLD.phone_verified THEN RAISE EXCEPTION 'Protected phone'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER protect_profile BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.austa_protect_profile_security_fields();
